// FIX APPLIED: strips ```json / ``` code fences before parsing,
// and reads from the AI Agent's actual output field ($json.output).
const items = $input.all();
const summaries = [];

for (const item of items) {
  let raw = item.json.output ?? item.json.text ?? item.json;

  if (typeof raw === 'string') {
    raw = raw
      .trim()
      .replace(/^```(?:json)?\s*/i, '')
      .replace(/```\s*$/i, '')
      .trim();
  }

  let parsed;
  try {
    parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch (e) {
    continue; // skip anything that wasn't valid JSON from the model
  }

  if (parsed && parsed.source && parsed.headline) {
    summaries.push(parsed);
  }
}

const successCount = summaries.length;
return [{
  json: {
    summaries,
    successCount,
    totalSources: 5,
    successLabel: `${successCount}/5 sources`
  }
}];

